## 6.5 Combining bullet chart and sparklines



::: {.cell}

```{.r .cell-code}
bullet <- coffeechain %>%
  filter(Date >= "2013-01-01") %>%
  group_by(`Product`) %>%
  summarise(`Target` = sum(`Budget Sales`),
            `Actual` = sum(`Sales`)) %>%
  ungroup() 

sales_data <- sales_data %>%
  left_join(bullet)

sales_data %>%
  gt() %>%
  gt_plt_sparkline('Monthly Sales') %>%
  gt_plt_bullet(column = Actual, 
                target = Target, 
                width = 28,
                palette = c("#A4A9D9", 
                          "black")) %>%
      fmt_number(columns = c(2,3,4),
    decimals = 0)%>%
  gt_theme_538()
```

